const assert=require('node:assert/strict');const {pathToFileURL}=require('node:url');const {chromium}=require(process.env.BODORI_QA_MODULE);const fs=require('node:fs');
(async()=>{
const browser=await chromium.launch({executablePath:process.env.BODORI_CHROME,args:['--no-sandbox','--allow-file-access-from-files'],headless:true});const page=await browser.newPage({viewport:{width:1360,height:1050}});const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.route(/fonts\.(googleapis|gstatic)\.com/,route=>route.abort());await page.goto(pathToFileURL(process.cwd()+'/bodori/index.html').href);
await page.locator('#beginStory').waitFor();assert.equal(await page.locator('.character.selected').count(),1);await page.locator('[data-locked="기이이표"]').click({force:true});assert.match(await page.locator('#selectionMessage').innerText(),/다음 버전/);
await page.locator('#beginStory').click();assert.match(await page.locator('.story-card').innerText(),/부산 토박이/);await page.locator('#skipStory').click();await page.waitForTimeout(150);assert.equal(await page.locator('#overlay').isVisible(),false);assert(await page.evaluate(()=>attackPower()===.7&&nextXP()===90));const x0=await page.evaluate(()=>player.x);await page.keyboard.down('ArrowRight');await page.waitForTimeout(180);await page.keyboard.up('ArrowRight');assert((await page.evaluate(()=>player.x))>x0);
await page.locator('#dodge').click();assert(await page.evaluate(()=>dodgeCD>0));await page.waitForTimeout(450);assert(await page.evaluate(()=>{invincible=poseTime=fear=0;const before=player.hp;const result=hurt(8,{x:player.x-40,y:player.y,kind:'senior'});draw();return result&&player.hp===before-8&&hurtLock>0&&invincible>0&&floatTexts.some(f=>f.kind==='hurt');}));assert.equal(await page.locator('.health-panel').getAttribute('data-hit'),'true');await page.waitForTimeout(700);
assert(await page.evaluate(()=>{player.x=coffee[0].x;player.y=coffee[0].y;player.hp=maxHP();update(.01);if(coffee[0].used)return false;player.hp-=20;update(.01);draw();return coffee[0].used&&player.hp===maxHP();}));await page.evaluate(()=>{gainXP(110);showGrowth()});await page.locator('#growGrit').click();assert(await page.evaluate(()=>growth.level===2&&growth.grit===1&&!paused));
for(let i=0;i<4;i++){await page.evaluate(i=>{running=true;paused=false;mode='play';hideOverlay();poseTime=0;strongCD=0;growth.pending=0;const e=enemies.find(e=>!e.dead);player.x=e.x-45;player.y=e.y;const oldRandom=Math.random;Math.random=()=>((i+.1)/4);pose=null;attack('strong');Math.random=oldRandom;draw();},i);await page.waitForTimeout(60);assert(await page.evaluate(i=>pose.id===ANTICS[i].id,i));}
await page.setViewportSize({width:390,height:844});await page.waitForTimeout(100);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert(await page.locator('#dodge').isVisible());assert((await page.locator('#normal').boundingBox()).width>=55);await page.screenshot({path:'/tmp/bodori-mobile.png',fullPage:true});
await page.evaluate(()=>{stage=3;rescuedIds.clear();setup();running=true;paused=false;growth.pending=0;for(const e of enemies)rescue(e);});assert(await page.evaluate(()=>mode==='bossintro'&&boss&&!boss.dead&&running));await page.locator('#overlayAction').click();await page.evaluate(()=>{growth.pending=0;paused=false;mode='play';hideOverlay();draw();boss.windup=.8;boss.pattern=1;draw();boss.pattern=0;draw();});assert(await page.locator('#bossHud').isVisible());for(const width of [390,1360]){await page.setViewportSize({width,height:1050});await page.waitForTimeout(100);const hud=await page.locator('#bossHud').boundingBox(),map=await page.locator('#game').boundingBox();assert(hud.y+hud.height<=map.y+1,'Boss bar must stay above the map');assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);}await page.evaluate(()=>{hitEnemy(boss,boss.max+1)});assert(await page.evaluate(()=>mode==='ending'&&boss.dead));await page.locator('#nextEnding').click();assert.match(await page.locator('.ending-card').innerText(),/내도 니 좋아한다/);await page.locator('#nextEnding').click();assert.match(await page.locator('.ending-card').innerText(),/사귀기 시작/);assert.deepEqual(errors,[]);await browser.close();console.log('PASS browser: startup, locked characters, Busan opening, movement, dodge, level choice, all antics, mobile layout, rebalanced starting stats, high-visibility recovery items and pickup, player damage/recoil/recovery, Jinhee boss spawning/tells/nonoverlapping HP row/defeat, romance ending; zero JS errors.');
})().catch(e=>{console.error(e);process.exit(1)});
